/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/**
 * Deepest level an issue may occupy. A root is level 0, and a placement is
 * refused when the deepest descendant would land below this.
 */
export const MAX_SUB_ISSUE_DEPTH: number = 3;

/**
 * Refused issue placement: the parent link would loop, or the subtree would
 * sit below `MAX_SUB_ISSUE_DEPTH`.
 */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or a descendant`
        : `Issue ${issueId} would sit deeper than the allowed sub-issue level`,
    );
    this.name = "IssueHierarchyError";
  }
}

