/** Direct live children, oldest first (creation time, then issue number). */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Every descendant at any depth, archived rows included, the root excluded. */
export async function listDescendantIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return (await walkDescendants(orgId, issueId)).issues;
}

/** Longest chain of descendants below `issueId`, in edges. A leaf is 0. */
export async function descendantHeight(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  return (await walkDescendants(orgId, issueId)).height;
}

export async function updateIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/**
 * Children of any archive state. Callers that want live rows only filter
 * afterwards — a live issue can sit under an archived ancestor, and both the
 * depth check and the archive cascade have to see past that ancestor.
 */
async function listByParentIds(
  orgId: OrgId,
  parentIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (parentIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.parentId, [...parentIds]),
          livePredicate(issues.archivedAt, { includeArchived: true }),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  return rows.map((row) => toIssue(row));
}

async function walkDescendants(
  orgId: OrgId,
  rootId: IssueId,
): Promise<{ issues: Issue[]; height: number }> {
  const collected: Issue[] = [];
  const seen = new Set<string>([rootId]);
  let frontier: IssueId[] = [rootId];
  let height = 0;

  while (frontier.length > 0) {
    const children = await listByParentIds(orgId, frontier);
    const next: IssueId[] = [];
    for (const child of children) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      collected.push(child);
      next.push(child.id);
    }
    if (next.length === 0) break;
    height += 1;
    frontier = next;
  }

  return { issues: collected, height };
}

