/**
 * Places `issueId` under `parentId`, or makes it a root when `parentId` is
 * null. Descendants keep their parent link, so they move with it. A refused
 * placement writes nothing and announces nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (issue.parentId === input.parentId) return issue;

  if (input.parentId === null) {
    await assertDepth(input.orgId, issue.id, 0);
  } else {
    const parent = await requireLiveProjectParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );
    if (parent.id === issue.id) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const parentLevel = await levelOf(input.orgId, parent, issue.id);
    await assertDepth(input.orgId, issue.id, parentLevel + 1);
  }

  const updated = await issueRepo.updateIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: updated.id,
    projectId: updated.projectId,
    changedFields: ["parentId"],
  });

  return updated;
}

/** Direct live sub-issues, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issueId);
}

/** Open and closed counts for every non-archived issue below `issueId`. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return rollupDescendants(orgId, issueId);
}

function isOpenStatus(status: IssueStatus): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * The parent of a new issue must be a live issue in the same project, and the
 * new leaf must land at or above `MAX_SUB_ISSUE_DEPTH`. A refusal happens
 * before a number is allocated, so nothing is inserted and nothing is announced.
 */
async function assertParentForCreate(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await requireLiveProjectParent(orgId, projectId, parentId);
  const parentLevel = await levelOf(orgId, parent, null);
  if (parentLevel + 1 > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(parent.id, "too_deep");
  }
}

async function requireLiveProjectParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Level of `start` (root = 0). Walking into `blockedId` means the placement
 * would put an issue under itself or under something below it.
 */
async function levelOf(
  orgId: OrgId,
  start: Issue,
  blockedId: IssueId | null,
): Promise<number> {
  if (blockedId !== null && start.id === blockedId) {
    throw new IssueHierarchyError(blockedId, "cycle");
  }

  let level = 0;
  let cursor = start.parentId;
  const seen = new Set<string>([start.id]);

  while (cursor !== null) {
    if (seen.has(cursor) || (blockedId !== null && cursor === blockedId)) {
      throw new IssueHierarchyError(blockedId ?? start.id, "cycle");
    }
    seen.add(cursor);
    const next = await issueRepo.findIssueById(orgId, cursor);
    if (next === null) break;
    level += 1;
    cursor = next.parentId;
  }

  return level;
}

/** Refuses a placement whose deepest descendant would pass the depth cap. */
async function assertDepth(
  orgId: OrgId,
  issueId: IssueId,
  newLevel: number,
): Promise<void> {
  const height = await issueRepo.descendantHeight(orgId, issueId);
  if (newLevel + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

async function rollupDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  const descendants = await issueRepo.listDescendantIssues(orgId, issueId);
  let open = 0;
  let closed = 0;
  for (const descendant of descendants) {
    if (isArchived(descendant)) continue;
    if (isOpenStatus(descendant.status)) open += 1;
    else closed += 1;
  }
  return { total: open + closed, open, closed };
}

/**
 * Tells a parent's assignee, once, when a direct sub-issue stops being open
 * and nothing open remains below that parent. Preferences and self-exclusion
 * are the fan-out's.
 */
async function notifySubIssuesCompleted(
  actor: Actor,
  orgId: OrgId,
  stopped: readonly Issue[],
): Promise<void> {
  const seenParents = new Set<string>();

  for (const issue of stopped) {
    if (issue.parentId === null || seenParents.has(issue.parentId)) continue;
    seenParents.add(issue.parentId);

    const parent = await issueRepo.findIssueById(orgId, issue.parentId);
    if (parent === null || isArchived(parent) || parent.assigneeId === null) {
      continue;
    }

    const rollup = await rollupDescendants(orgId, parent.id);
    if (rollup.open > 0) continue;

    await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
      title: "Sub-issues completed",
      body: `The last open sub-issue under "${parent.title}" is closed`,
      href: `/issues/${parent.id}`,
      actorId: actor.userId,
    });
  }
}

