import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("hier");
  other = await createTenant("hier-other");
});

afterAll(() => cleanup());

function input(title: string, extra: Record<string, unknown> = {}) {
  return {
    ...issueInput(tenant.org.id, tenant.project.id, { title }),
    ...extra,
  };
}

async function make(title: string, extra: Record<string, unknown> = {}): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, input(title, extra) as never);
}

describe("issue hierarchy", () => {
  it("places, lists, rolls up, and refuses cycles and depth", async () => {
    const root = await make("Root", { assigneeId: tenant.userIds.admin });
    const child = await make("Child", { parentId: root.id });
    const grand = await make("Grand", { parentId: child.id, status: "done" });
    const great = await make("Great", { parentId: grand.id });

    await expect(
      make("Too deep", { parentId: great.id }),
    ).rejects.toMatchObject({ reason: "too_deep" });

    const created = captureCount();
    await expect(make("Too deep again", { parentId: great.id })).rejects.toBeInstanceOf(
      IssueHierarchyError,
    );
    expect(created()).toBe(0);
    expect(await issueRepo.findIssueByNumber(tenant.org.id, tenant.project.id, 999)).toBeNull();

    const subs = await issueService.listSubIssues(tenant.actors.viewer, tenant.org.id, root.id);
    expect(subs.map((issue) => issue.id)).toEqual([child.id]);

    expect(await issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, root.id)).toEqual({
      total: 3,
      open: 2,
      closed: 1,
    });

    const events: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => events.push(payload));
    try {
      const moved = await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: great.id,
        parentId: root.id,
      });
      expect(moved.parentId).toBe(root.id);
      expect(events).toHaveLength(1);
      expect(events[0]).toMatchObject({ changedFields: ["parentId"], issueId: great.id });
    } finally {
      off();
    }

    const same = captureUpdated();
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: great.id,
      parentId: root.id,
    });
    expect(same()).toBe(0);

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: root.id,
        parentId: child.id,
      }),
    ).rejects.toMatchObject({ reason: "cycle" });
    const still = await issueRepo.findIssueById(tenant.org.id, root.id);
    expect(still?.parentId).toBeNull();

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: great.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });
    expect((await issueRepo.findIssueById(tenant.org.id, child.id))?.parentId).toBe(root.id);
  });

  it("rejects a parent in another project, an archived parent, and a missing issue", async () => {
    const root = await make("P root");
    const otherProject = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELSE",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#000000",
      targetDate: null,
