        parentId: great.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });
    expect((await issueRepo.findIssueById(tenant.org.id, child.id))?.parentId).toBe(root.id);
  });

  it("rejects a parent in another project, an archived parent, and a missing issue", async () => {
    const root = await make("P root");
    const otherProject = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELSE",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#000000",
      targetDate: null,
    });
    const foreign = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, otherProject.id, { title: "Other project" }),
    );

    await expect(make("Cross", { parentId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: root.id,
        parentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, foreign.id);
    const fresh = await make("Fresh");
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: fresh.id,
        parentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: fresh.id,
        parentId: root.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.listSubIssues(tenant.actors.member, other.org.id, root.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, foreign.id),
    ).resolves.toEqual({ total: 0, open: 0, closed: 0 });

    await expect(
      issueService.getIssueRollup(
        tenant.actors.member,
        tenant.org.id,
        other.project.id as never,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("archives the live subtree once and preserves already archived rows", async () => {
    const root = await make("Arc root");
    const live = await make("Arc live", { parentId: root.id });
    const done = await make("Arc done", { parentId: root.id, status: "canceled" });
    const old = await make("Arc old", { parentId: live.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, old.id);
    const stamped = (await issueRepo.findIssueById(tenant.org.id, old.id))?.archivedAt;

    const events: string[] = [];
    const off = subscribe("issue.archived", (payload) => events.push(payload.issueId));
    try {
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, root.id);
    } finally {
      off();
    }

    expect(new Set(events)).toEqual(new Set([root.id, live.id, done.id]));
    expect(events).toHaveLength(3);
    expect((await issueRepo.findIssueById(tenant.org.id, old.id))?.archivedAt).toBe(stamped);
    expect((await issueRepo.findIssueById(tenant.org.id, root.id))?.archivedAt).not.toBeNull();
  });

  it("notifies the parent assignee when the last open sub-issue closes, once", async () => {
    const parent = await make("Notify parent", { assigneeId: tenant.userIds.admin });
    const openA = await make("Open A", { parentId: parent.id });
    const openB = await make("Open B", { parentId: parent.id });
    const nested = await make("Nested", { parentId: openB.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: openA.id,
      status: "done",
    });
    expect(await notes()).toHaveLength(0);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: nested.id,
      status: "canceled",
    });
    expect(await notes()).toHaveLength(0);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: openB.id,
      status: "done",
    });
    const first = await notes();
    expect(first).toHaveLength(1);
    expect(first[0]?.kind).toBe("sub_issues_completed");
    expect(first[0]?.recipientId).toBe(tenant.userIds.admin);
    expect(first[0]?.actorId).toBe(tenant.userIds.member);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: openB.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: openB.id,
      status: "done",
    });
    expect(await notes()).toHaveLength(2);

    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: openA.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: openA.id,
      status: "done",
    });
    expect(await notes()).toHaveLength(2);
  });

  it("notifies when the last open sub-issue is archived, and not when it is moved away", async () => {
    const parent = await make("Arch parent", { assigneeId: tenant.userIds.owner });
    const child = await make("Arch child", { parentId: parent.id });

    const before = (await notesFor(tenant.userIds.owner)).length;
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: null,
    });
    expect(await notesFor(tenant.userIds.owner)).toHaveLength(before);

    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: parent.id,
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);
    const rows = await notesFor(tenant.userIds.owner);
    expect(rows.filter((row) => row.kind === "sub_issues_completed")).toHaveLength(1);
  });

  it("lists direct children oldest first, skipping archived", async () => {
    const root = await make("Order root");
    const first = await make("First", { parentId: root.id });
    const second = await make("Second", { parentId: root.id });
    const third = await make("Third", { parentId: root.id });
    getDb()
      .update(issues)
      .set({ createdAt: first.createdAt })
      .where(eq(issues.id, second.id))
      .run();
    getDb()
      .update(issues)
      .set({ createdAt: first.createdAt })
      .where(eq(issues.id, third.id))
      .run();
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, second.id);

    const listed = await issueService.listSubIssues(
      tenant.actors.member,
      tenant.org.id,
      root.id,
    );
    expect(listed.map((issue) => issue.id)).toEqual([first.id, third.id]);
  });
});

function captureCount(): () => number {
  let n = 0;
  const off = subscribe("issue.created", () => {
    n += 1;
  });
  return () => {
    off();
    return n;
  };
}

function captureUpdated(): () => number {
  let n = 0;
  const off = subscribe("issue.updated", () => {
    n += 1;
  });
  return () => {
    off();
    return n;
  };
}

async function notes() {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function notesFor(userId: Tenant["userIds"]["owner"]) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}
